using System.Reflection;

namespace Facilitator.Tests.ScenarioGate;

/// <summary>
/// The scenario gate's fail-closed law over its own manifest
/// (<c>docs/scenarios/scenario-bindings.json</c>, generated by
/// <c>tools/scenario-plane/gen-bindings.py</c> and hand-reviewed):
/// every approved scenario carries a verdict, every bare dotnet evidence id
/// is a method that exists on a class in THIS assembly right now (the
/// <c>ScenarioWalks:</c>-prefixed half resolves in
/// <c>Facilitator.ScenarioWalks</c> via
/// <see cref="ScenarioEvidenceResolutionTestsBase"/>), every js evidence
/// path exists on disk, and the manifest covers exactly the ids in
/// <c>approved-scenarios.md</c>. A renamed test or a deleted scenario turns
/// the gate red instead of quietly rotting the audit record.
/// </summary>
public sealed class ScenarioBindingsTests : ScenarioEvidenceResolutionTestsBase
{
    /// <inheritdoc />
    protected override Assembly Subject => typeof(ScenarioBindingsTests).Assembly;

    /// <inheritdoc />
    protected override string EvidencePrefix => "";

    public static TheoryData<string> ScenarioIds() => AllScenarioIds();

    [Theory]
    [MemberData(nameof(ScenarioIds))]
    public void EveryEvidenceIdResolves(string id) => ResolveEvidenceFor(id);

    [Fact]
    public void ManifestCoversTheCatalogExactly()
    {
        var catalog = File.ReadAllText(Path.Combine(RepoRoot, "docs", "scenarios", "approved-scenarios.md"));
        var positives = System.Text.RegularExpressions.Regex
            .Matches(catalog, @"^### ([A-Z]\d+) —", System.Text.RegularExpressions.RegexOptions.Multiline)
            .Select(m => m.Groups[1].Value).ToList();
        var negatives = System.Text.RegularExpressions.Regex
            .Matches(catalog, @"^\| (N\d+) \|", System.Text.RegularExpressions.RegexOptions.Multiline)
            .Select(m => m.Groups[1].Value).ToList();
        var want = positives.Concat(negatives).Order(StringComparer.Ordinal).ToList();
        var have = Load().Select(b => b.Id).Order(StringComparer.Ordinal).ToList();
        Assert.Equal(want, have);
    }

    [Fact]
    public void ManualLaneMatchesTiers()
    {
        foreach (var b in Load())
        {
            if (b.Tier == "T4")
            {
                Assert.Equal("T4-manual", b.Lane);
            }
            else
            {
                Assert.NotEqual("T4-manual", b.Lane);
            }
        }
    }
}
